import networkx as nx

def solve_for_N(N):
    # Black squares (i, j) where i+j is even, 1 <= i, j <= N
    black_squares = []
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if (i + j) % 2 == 0:
                black_squares.append((i, j))

    B = len(black_squares)
    G = nx.Graph()
    for k in range(B):
        for l in range(k + 1, B):
            r1, c1 = black_squares[k]
            r2, c2 = black_squares[l]
            if abs(r1 - r2) == 1 and abs(c1 - c2) == 1:
                G.add_edge(k, l)

    matching = nx.max_weight_matching(G, maxcardinality=True) # Wait, this is max matching
    # nx.max_weight_matching doesn't have maxcardinality, use max_matching
    matching = nx.max_matching(G)
    m = len(matching)
    return B, m

for N in [3, 5, 7, 9]:
