    color = {}
    for node in G.nodes():
        if node not in color:
            color[node] = 0
            stack = [node]
            while stack:
                u = stack.pop()
                for v in G.neighbors(u):
                    if v not in color:
                        color[v] = 1 - color[u]
                        stack.append(v)

